import{z as A,x as i,o as r,c as B,q as u,j as E,D as e,d as t,s as o,S as s,b as l}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"Tulu / Tulu 2 / Tulu 3","description":"","frontmatter":{"title":"Tulu / Tulu 2 / Tulu 3","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/tulu.md","filePath":"llm/tulu.md","lastUpdated":1791413859000}'),T={name:"llm/tulu.md"};function p(m,a,d,F,L,c){const n=i("Mermaid");return r(),B("div",null,[a[2]||(a[2]=u('<h1 id="tulu-tulu-2-tulu-3" tabindex="-1">Tulu / Tulu 2 / Tulu 3 <a class="header-anchor" href="#tulu-tulu-2-tulu-3" aria-label="Permalink to &quot;Tulu / Tulu 2 / Tulu 3&quot;">​</a></h1><div class="epigraph"><p>没有单一指令集在所有评测上同时最好；后训练的进步来自把数据混合物、偏好方法和可验证奖励拆开测量，而不是换一个更响亮的聊天名字。</p><footer>—— Ivison / Wang 等 Tulu；Ivison 等 Tulu 2；Lambert 等 Tulu 3，Allen Institute for AI</footer></div><p>Allen Institute for AI 的 Tulu（写作 TÜLU）不是某一个基座架构，而是一套<strong>把后训练做成可复现实验</strong>的配方：公开混合物、公开代码、按技能拆开的评测，以及从 7B 到几十上百亿的全参检查点。2023 年的 <em>How Far Can Camels Go?</em> 用 LLaMA 扫了约十二个公开指令集，给出第一代 Tulu 混合物；同年的 <em>Camels in a Changing Climate</em> 换成 Llama 2，引入 <a href="/llm/dpo">DPO</a> 与 UltraFeedback，把开放聊天推到当时 GPT-3.5 附近；2024–2025 年的 Tulu 3 再叠第四段——用程序可检查的奖励做强化学习（RLVR），并覆盖 Llama 3.1 与 <a href="/llm/olmoe">OLMo</a> 家族。本篇按三篇论文的贡献写：技能会随数据源分化、偏好阶段改的是开放生成而不是所有基准、可验证奖励只在有真值的任务上补第三种梯度。工程仓库 <code>open-instruct</code> 后来会改超参，脊梁仍是这三次测量。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指令微调在 2023 年已经有许多公开资源：人工众包（OpenAssistant、Dolly）、教师蒸馏（Alpaca、Vicuna 式 ShareGPT）、带思维链的 FLAN 变体。实验室习惯的做法是「选一个当时最火的集，报一张 Arena 或 GPT-4 裁判表」。这会把三件事缠死。第一，不同来源强化的技能不同——代码、多语、安全和开放写作并不共享同一条损失面。第二，人类或模型偏好评分对知识与推理的分辨力很弱，Tulu 原文明确写了：偏好评测与基准评测暴露的能力差对不上。第三，没有共同的开发/留出协议时，混合物很容易污染评测题面，分数变成记忆。</p><p>Ai2 要回答的不是「再训一个更会聊天的 LLaMA」，而是：在<strong>只使用公开数据</strong>的约束下，后训练还能把哪些技能推到多近闭源助手，以及每一步（SFT、偏好、RL）各自买到了什么。这要求把评测写成技能向量，而不是一个平均「有用性」。</p><p><span class="marginnote">术语翻译：后训练就是「预训练完的毛坯模型」到「能用的助手」之间所有工序的统称。SFT（监督微调）是拿示范问答让它模仿；偏好训练（DPO 一类）是给它看成对答案、学哪个更好；RL（强化学习）是只告诉它「这个答案对/不对」，让它自己试错。</span></p><h3 id="技能向量而不是一张排行榜" tabindex="-1">技能向量而不是一张排行榜 <a class="header-anchor" href="#技能向量而不是一张排行榜" aria-label="Permalink to &quot;技能向量而不是一张排行榜&quot;">​</a></h3><p>第一篇骆驼论文把评测拆成事实知识、推理、多语、代码、安全与开放指令遵循，并用自动指标、模型裁判和人工对照一起看。结论很不讨喜：没有一个数据集或简单拼接在所有轴上同时最优；某个集在 MMLU 类知识上好看，换到开放写作就塌。Tulu 混合物是折中，不是发现了「唯一正确的指令分布」。把 Tulu 理解成「数据越多越好的汇编」，会丢掉这篇论文真正的方法贡献——<strong>用同一套基座扫来源，逼出技能与来源的对应关系</strong>。<span class="marginnote">Tulu 这个名字来自骆驼，不是新的预训练目标。权重挂在别人的基座上（LLaMA / Llama 2 / Llama 3.1 / OLMo 2），贡献在后训练配方与评测协议。和只开聊天权重、不公开混合物与超参的模型，不是同一类可引用对象。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三代配方可以收成一条加长的管道，每代只加一段，并重做混合物。</p><p><strong>Tulu（2023）</strong>。基座是 LLaMA 6.7B 到 65B。监督数据来自约十二个公开指令集，从人工策划到合成蒸馏都有；最终 Tulu 混合物把高质量开放资源拼在一起做全参微调。论文同时放出整套指令微调模型，便于别人只换一个来源做对照。关键实验发现是：来源会「揭开或增强」特定技能，单集做不到全能；当时最好的开放指令模型在他们的套件上平均约到 ChatGPT 的 87%、GPT-4 的 73%，缺口同时来自基座与数据。</p><p><strong>Tulu 2（2023）</strong>。基座换成 Llama 2（另有 Code Llama 上的 Code Tulu 2）。混合物 V2 相对 V1 做了两件事：加入当时新的高质量蒸馏（如 Evol-Instruct、OpenOrca 一类解释痕迹），并<strong>削减</strong>过大的 FLAN 切片——他们发现少而精的混合物在 7B 上平均大约好 8%，与「高质量少量示范」的方向一致。第二段是 DPO：在 SFT 之后用 UltraFeedback（约 6.4 万条、GPT-4 排序的完成）做偏好，学习率低到 \\(5\\times 10^{-7}\\)，\\(\\beta=0.1\\)，约三轮。DPO 把 AlpacaEval 一类开放生成抬了一大截（论文报平均约 13% 量级），对多数能力基准没有系统性毁掉；多语（TyDiQA）会掉，因为偏好数据几乎没有多语。Tulu 2+DPO 70B 是当时公开的最大 DPO 模型之一，AlpacaEval 与 MT-Bench 进入开放权重前列，Chatbot Arena 上与 GPT-3.5-turbo-0314 同一档。他们还测了 <a href="/llm/qlora">QLoRA</a>：长文开放生成上全参明显强于 QLoRA，差距随宽度缩小。</p><p><span class="marginnote">数字实例：\\(5\\times 10^{-7}\\) 这个学习率比常见 SFT 学习率（\\(10^{-5}\\) 到 \\(2\\times 10^{-5}\\)）小一到两个数量级。偏好训练只许「轻轻挪」输出分布——步子一大，模型会为了更像赢回答而牺牲知识 accuracy，这也是偏好阶段经常掉能力基准的原因之一。</span></p><p><strong>Tulu 3（2024）</strong>。管道收成四段：先为技能定向策数据并相对 Tulu 3 Eval <strong>去污染</strong>；再 SFT；再 DPO（在策略合成偏好加离线偏好上扫混合物）；最后 <strong>RLVR</strong>——Reinforcement Learning with Verifiable Rewards。RLVR 不训奖励模型，只在有程序真值的任务上给 0/1：数学（GSM8K、MATH 一类）与可检查的指令约束（<a href="/llm/ifeval">IFEval</a> 式格式）。奖励来自验证器，优化仍是策略梯度族。模型覆盖 Llama 3.1 的 8B / 70B / 405B 以及 OLMo 2；70B 在他们的核心技能平均上超过 Llama 3.1 70B Instruct 等同期开放指令模型。公开对象包括数据、代码、评测与配方，而不只是权重。</p>',15)),(r(),E(s,null,{default:e(()=>[o(n,{id:"mermaid-43",class:"mermaid",graph:"flowchart%20TD%0A%20%20B%5B%22%E9%A2%84%E8%AE%AD%E7%BB%83%E5%9F%BA%E5%BA%A7%22%5D%20--%3E%20SFT%5B%22SFT%EF%BC%9A%E5%85%AC%E5%BC%80%E6%B7%B7%E5%90%88%E7%89%A9%22%5D%0A%20%20SFT%20--%3E%20DPO%5B%22DPO%EF%BC%9AUltraFeedback%20%2F%20%E5%9C%A8%E7%AD%96%E7%95%A5%E5%81%8F%E5%A5%BD%22%5D%0A%20%20DPO%20--%3E%20RLVR%5B%22RLVR%EF%BC%9A%E5%8F%AF%E9%AA%8C%E8%AF%81%200%2F1%20%E5%A5%96%E5%8A%B1%22%5D%0A%20%20SFT%20--%3E%20E%5B%22%E6%8A%80%E8%83%BD%E5%90%91%E8%AF%84%E6%B5%8B%E5%A5%97%E4%BB%B6%22%5D%0A%20%20DPO%20--%3E%20E%0A%20%20RLVR%20--%3E%20E%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h3",{id:"偏好阶段买的是开放生成",tabindex:"-1"},[t("偏好阶段买的是开放生成 "),l("a",{class:"header-anchor",href:"#偏好阶段买的是开放生成","aria-label":'Permalink to "偏好阶段买的是开放生成"'},"​")],-1)),a[4]||(a[4]=l("p",null,"Tulu 2 已经把这件事写清楚：DPO 主要抬 Arena / AlpacaEval / MT-Bench，对知识与推理基准常常近似平移。Tulu 3 把偏好数据改成「选定提示上的在策略合成 + 离线」，并继续用技能套件守住不要为聊天而牺牲数学。若只用 GPT-4 当裁判、又用 GPT-4 排序的偏好集训练，分数会自我强化；Ai2 因此保留非裁判基准，并把开发与留出拆开。读 Tulu 的「超过 GPT-3.5」必须看是哪一张表：开放写作、Arena 与 MMLU 不是同一个索赔。",-1)),a[5]||(a[5]=l("h2",{id:"机制",tabindex:"-1"},[t("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=l("p",null,"后训练的梯度来源在三代里逐步加宽。SFT 是教师或标注员完成上的交叉熵，定义「助手该如何开口」。DPO 把成对比较写成策略相对参照的对数比，推动「更像赢回答、不像输回答」，但不引入新的真值。RLVR 只在验证器能判定对错的子集上给稀疏奖励，把数学最终答案和格式约束变成可优化的标量。三者不是互相替代：SFT 给分布，DPO 给主观偏好，RLVR 给可检查任务上的正确性。跳过 SFT 直接 RL，策略往往不会格式化地写出可解析答案；只用 DPO 而不做 RLVR，数学的对错没有进入损失。",-1)),(r(),E(s,null,{default:e(()=>[o(n,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BF%99%E6%AE%B5%E8%AE%AD%E7%BB%83%E7%94%A8%E4%BB%80%E4%B9%88%E4%BF%A1%E5%8F%B7%3F%22%5D%20--%3E%20S%5B%22SFT%EF%BC%9A%E7%A4%BA%E8%8C%83%E5%AE%8C%E6%88%90%E4%B8%8A%E7%9A%84%E4%BA%A4%E5%8F%89%E7%86%B5%22%5D%0A%20%20Q%20--%3E%20D%5B%22DPO%EF%BC%9A%E6%88%90%E5%AF%B9%E5%81%8F%E5%A5%BD%20%C2%B7%20%E5%AF%B9%E6%95%B0%E6%AF%94%22%5D%0A%20%20Q%20--%3E%20R%5B%22RLVR%EF%BC%9A%E9%AA%8C%E8%AF%81%E5%99%A8%200%2F1%20%E5%A5%96%E5%8A%B1%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E4%B9%B0%E5%88%B0%EF%BC%9A%E5%8A%A9%E6%89%8B%E7%9A%84%E5%9F%BA%E6%9C%AC%E5%88%86%E5%B8%83%E4%B8%8E%E6%A0%BC%E5%BC%8F%22%5D%0A%20%20D%20--%3E%20D1%5B%22%E4%B9%B0%E5%88%B0%EF%BC%9A%E5%BC%80%E6%94%BE%E7%94%9F%E6%88%90%E7%9A%84%E4%B8%BB%E8%A7%82%E5%81%8F%E5%A5%BD%22%5D%0A%20%20R%20--%3E%20R1%5B%22%E4%B9%B0%E5%88%B0%EF%BC%9A%E5%8F%AF%E6%A3%80%E6%9F%A5%E4%BB%BB%E5%8A%A1%E7%9A%84%E6%AD%A3%E7%A1%AE%E6%80%A7%22%5D%0A%20%20S1%20--%3E%20N%5B%22%E4%BA%92%E8%A1%A5%EF%BC%8C%E4%B8%8D%E4%BA%92%E7%9B%B8%E6%9B%BF%E4%BB%A3%22%5D%0A%20%20D1%20--%3E%20N%0A%20%20R1%20--%3E%20N%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=u('<p>去污染是 Tulu 3 的方法学贡献，不只是卫生条款。后训练数据若含评测题面，SFT 会变成背题。他们强调提示相对评测套件去重，并把评测分成开发用与留出未见。没有这一步，混合物消融无法解释。</p><p><span class="marginnote">直觉类比：去污染像考前把题库里的原题从练习册里抽走。留着原题，学生的「模拟考分数」只是背题成绩；模型同理——训练数据混进评测题，消融实验比的是谁背得多，不是谁真的会。</span></p><p><span class="marginnote">RLVR 与后来流行的 <a href="/llm/grpo">GRPO</a> / 结果监督同属「可检查任务上的 RL」，但 Tulu 3 论文的主张是配方级的：在开放后训练栈里加第四段，而不是提出一种新的优势估计器。复现时应看他们的验证器定义与提示集，而不是把任意数学 RL 都叫做 Tulu 3。</span></p><h3 id="基座更换不等于配方作废" tabindex="-1">基座更换不等于配方作废 <a class="header-anchor" href="#基座更换不等于配方作废" aria-label="Permalink to &quot;基座更换不等于配方作废&quot;">​</a></h3><p>从 LLaMA 到 Llama 2 再到 Llama 3.1 / OLMo 2，同一套「混合物 + DPO +（后来的）RLVR」被重跑。论文要证明的是配方可迁移，不是某一个检查点永远 SOTA。Code Tulu 2 额外说明：继续代码预训练的基座，再用通用 V2 混合物微调，代码基准上升、AlpacaEval 一类开放写作大约掉两成量级——后训练不能把预训练域的偏置完全洗掉。选基座仍然是后训练的第一超参。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>Tulu 系列的上限受公开数据与公开教师约束。混合物里大量 GPT-4 / ChatGPT 完成，许可证、污染和「学教师口吻」都在。用 GPT-4 裁判评开放生成，会偏爱像 GPT 的学生；Arena 能部分校正，但不能消掉训练分布本身。安全与多语在早期混合物里偏弱，Tulu 2 的 TyDiQA 回退是明确失败模式，不是脚注。</p><p>RLVR 只覆盖验证器能写出来的任务。开放写作、模糊建议、多约束但不可程序化的指令，没有 0/1。把 RLVR 当成通用对齐，会在没有真值的轴上无梯度，甚至因数学专项而风格漂移。405B 级实验证明配方能上规模，并不证明每个实验室都付得起同一套扫混合物的预算。</p><p><span class="marginnote">不要把 Hugging Face 上某个 <code>tulu-*-instruct</code> 权重直接当成对应论文的全部声明。日期后缀、是否含 DPO、是否含 RLVR、基座是 Llama 还是 OLMo，必须对模型卡。引用贡献时指向三篇论文与 <code>allenai/open-instruct</code>，而不是某一个 7B 聊天文件。</span></p><p>与只谈人写/合成配比的文章相比，Tulu 的单位是<strong>可消融的后训练阶段</strong>。它不替代 <a href="/llm/sft-data-sources">指令数据清洗</a>，而是假定你已经能把来源标签进混合物，再问阶段与技能的因果。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Tulu 把开放后训练收成可复现配方：公开混合物、按技能拆开的评测、以及可对照的全参检查点。</li><li>第一代表明不同指令来源对应不同技能，偏好评测覆盖不了基准上的能力差。</li><li>Tulu 2 换 Llama 2、收紧混合物，并用 UltraFeedback 上的 DPO 抬开放生成；QLoRA 在长文上弱于全参。</li><li>Tulu 3 加去污染、在策略偏好与 RLVR，使数学和可检查指令遵循进入第四段梯度。</li><li>DPO 主要买聊天与写作；RLVR 只在有验证器的任务上买正确性；二者都不替代基座与 SFT 分布。</li><li>出处：Wang / Ivison 等，<em>How Far Can Camels Go?</em>，2023；Ivison 等，<em>Camels in a Changing Climate</em>，arXiv:2311.10702；Lambert 等，<em>Tülu 3: Pushing Frontiers in Open Language Model Post-Training</em>，arXiv:2411.15124。代码 <a href="https://github.com/allenai/open-instruct%E3%80%82" target="_blank" rel="noreferrer">https://github.com/allenai/open-instruct。</a></li></ul>',12))])}const P=A(T,[["render",p]]);export{D as __pageData,P as default};
